const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const isScheduledTrigger = Boolean(raw && (raw.timestamp || raw.readableSchedule || raw.rule));
const notifType = isScheduledTrigger ? 'SCAN_DUE_JOBS' : (input.notification_type || input.event_type || 'REQUEST_RECEIVED');

const aptId = input.appointment_id || 'apt-mock-' + Date.now();
const orgId = input.organization_id || '00000000-0000-0000-0000-000000000001';
const version = Number(input.version || input.appointment_version || 1);
const recipientPhone = input.owner_phone || input.recipient_phone || '+573105550199';
const recipientName = input.owner_name || input.recipient_name || 'Tutor';
const petName = input.pet_name || 'Paciente';
const vetName = input.vet_name || input.veterinarian_name || 'Dr. Luis Eduardo Ríos';
const scheduledTime = input.scheduled_time || input.start_time || new Date(Date.now() + 86400000).toISOString();
const addressSummary = input.address_summary || input.address || 'Bogotá, Colombia';
const okvetRef = input.okvet_reference || input.okvet_appointment_id || null;
const okvetValidated = input.okvet_validated === true || Boolean(okvetRef);

let templateCode = 'vet_appointment_request_received';
let isOfficial = false;
let dispatchStatus = 'PENDING_VALIDATION';
let rejectionReason = null;
let templateParams = {};

switch (notifType) {
  case 'SCAN_DUE_JOBS':
    return {
      json: {
        action: 'EXECUTE_DUE_JOBS_SCAN',
        status: 'SCAN_COMPLETED',
        organization_id: orgId,
        scanned_at: new Date().toISOString(),
        message: 'Scheduled check for due appointment notification jobs completed successfully',
        send_enabled: false
      }
    };

  case 'CONFIRMED_OFFICIAL':
    if (!okvetValidated || !okvetRef) {
      dispatchStatus = 'OKVET_GATE_BLOCKED';
      rejectionReason = 'OKVET_REFERENCE_REQUIRED: Cannot confirm appointment without verified OKVET clinical reference';
    } else {
      isOfficial = true;
      templateCode = 'vet_appointment_confirmed';
      dispatchStatus = 'CONFIRMED_DISPATCH_ENQUEUED';
      templateParams = {
        owner_name: recipientName,
        pet_name: petName,
        date: scheduledTime.split('T')[0],
        time_window: scheduledTime.includes('T') ? scheduledTime.split('T')[1].substring(0, 5) : scheduledTime,
        veterinarian_name: vetName,
        okvet_reference: okvetRef
      };
    }
    break;

  case 'REMINDER_24H':
    templateCode = 'vet_appointment_reminder_24h';
    dispatchStatus = 'REMINDER_24H_ENQUEUED';
    templateParams = {
      owner_name: recipientName,
      pet_name: petName,
      date: scheduledTime.split('T')[0],
      time_window: scheduledTime.includes('T') ? scheduledTime.split('T')[1].substring(0, 5) : scheduledTime,
      address: addressSummary
    };
    break;

  case 'REMINDER_2H':
    templateCode = 'vet_veterinarian_on_the_way';
    dispatchStatus = 'REMINDER_2H_ENQUEUED';
    templateParams = {
      owner_name: recipientName,
      pet_name: petName,
      time_window: scheduledTime.includes('T') ? scheduledTime.split('T')[1].substring(0, 5) : scheduledTime,
      veterinarian_name: vetName
    };
    break;

  case 'RESCHEDULE_PROPOSAL':
    templateCode = 'vet_appointment_reschedule_proposal';
    dispatchStatus = 'RESCHEDULE_PROPOSAL_ENQUEUED';
    templateParams = {
      owner_name: recipientName,
      pet_name: petName,
      proposed_date: (input.proposed_start || scheduledTime).split('T')[0],
      reason: input.reason || 'Ajuste logístico de ruta'
    };
    break;

  case 'RESCHEDULE_CONFIRMED':
    if (!okvetValidated || !okvetRef) {
      dispatchStatus = 'OKVET_GATE_BLOCKED';
      rejectionReason = 'OKVET_REFERENCE_REQUIRED: Reschedule confirmation requires verified OKVET reference';
    } else {
      isOfficial = true;
      templateCode = 'vet_appointment_rescheduled';
      dispatchStatus = 'RESCHEDULE_CONFIRMED_ENQUEUED';
      templateParams = {
        owner_name: recipientName,
        pet_name: petName,
        new_date: scheduledTime.split('T')[0],
        veterinarian_name: vetName,
        okvet_reference: okvetRef
      };
    }
    break;

  case 'CANCELLED':
  case 'CANCELLATION_CONFIRMED':
    templateCode = 'vet_appointment_cancelled';
    dispatchStatus = 'CANCELLATION_NOTICE_ENQUEUED';
    templateParams = {
      owner_name: recipientName,
      pet_name: petName,
      date: scheduledTime.split('T')[0],
      reason: input.reason || 'Cancelación solicitada'
    };
    break;

  case 'NO_SHOW_FOLLOWUP':
    templateCode = 'vet_appointment_no_show_followup';
    dispatchStatus = 'RECOVERY_NOTICE_ENQUEUED';
    templateParams = {
      owner_name: recipientName,
      pet_name: petName,
      support_phone: '+573105550199'
    };
    break;

  case 'WAITLIST_OFFER':
    templateCode = 'vet_waitlist_offer';
    dispatchStatus = 'WAITLIST_OFFER_ENQUEUED';
    templateParams = {
      owner_name: recipientName,
      pet_name: petName,
      offered_slot: scheduledTime,
      expires_in_minutes: '60'
    };
    break;

  default:
    templateCode = 'vet_appointment_request_received';
    dispatchStatus = 'REQUEST_RECEIVED_ENQUEUED';
    templateParams = {
      owner_name: recipientName,
      pet_name: petName,
      status: 'Recibida - En revisión por coordinación clínica'
    };
}

const dispatchPayload = {
  organization_id: orgId,
  appointment_id: aptId,
  appointment_version: version,
  notification_type: notifType,
  is_official_confirmation: isOfficial,
  okvet_validated: okvetValidated,
  okvet_reference: okvetRef,
  recipient_phone: recipientPhone,
  recipient_name: recipientName,
  pet_name: petName,
  veterinarian_name: vetName,
  status: dispatchStatus,
  rejection_reason: rejectionReason,
  core_03_request: {
    message_category: 'UTILITY',
    message_purpose: notifType,
    recipient_phone: recipientPhone,
    recipient_name: recipientName,
    template_code: templateCode,
    template_parameters: templateParams,
    business_entity_type: 'APPOINTMENT',
    business_entity_id: aptId,
    business_entity_version: version,
    idempotency_key: 'apt-notif-' + orgId + '-' + aptId + '-v' + version + '-' + notifType,
    send_enabled: (Boolean(input.send_enabled) || Boolean(process.env.WHATSAPP_SEND_ENABLED === 'true'))
  },
  send_enabled: (Boolean(input.send_enabled) || Boolean(process.env.WHATSAPP_SEND_ENABLED === 'true')),
  processed_at: new Date().toISOString()
};

return { json: dispatchPayload };
